<?php
require_login();if(is_admin())redirect('?page=admin&tab=orders');$uid=(int)$_SESSION['user']['id'];
$statusLabels=['Diproses','Dikemas','Dikirim','Selesai','Dibatalkan'];$filter=is_string($_GET['status']??null)?$_GET['status']:'';if(!in_array($filter,$statusLabels,true))$filter='';
$stmt=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$stmt->bind_param('i',$uid);$stmt->execute();$allOrders=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();$counts=array_count_values(array_column($allOrders,'status'));$orders=$filter?array_values(array_filter($allOrders,static fn($o)=>$o['status']===$filter)):$allOrders;
$stmt=db()->prepare('SELECT oi.*,p.image FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN products p ON p.id=oi.product_id WHERE o.user_id=? ORDER BY oi.id');$stmt->bind_param('i',$uid);$stmt->execute();$orderItems=[];foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $item)$orderItems[$item['order_id']][]=$item;$stmt->close();
$stmt=db()->prepare('SELECT pi.* FROM order_payment_instructions pi JOIN orders o ON o.id=pi.order_id WHERE o.user_id=?');$stmt->bind_param('i',$uid);$stmt->execute();$paymentSnapshots=[];foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $snapshot)$paymentSnapshots[$snapshot['order_id']]=json_decode($snapshot['settings_json'],true);$stmt->close();
?>
<section class="customer-workspace section container"><div class="customer-page-heading"><p>MY PURCHASES</p><h1>Pesanan saya</h1><span>Lihat detail, pantau pengiriman, atau batalkan pesanan sebelum dikirim.</span></div><div class="customer-layout"><?php include __DIR__.'/../includes/customer-account-menu.php'; ?><div class="customer-content">
<nav class="customer-order-tabs" aria-label="Filter pesanan"><a href="?page=orders" <?= $filter===''?'aria-current="page"':'' ?>>Semua <b><?= count($allOrders) ?></b></a><?php foreach($statusLabels as $label): ?><a href="?page=orders&amp;status=<?= urlencode($label) ?>" <?= $filter===$label?'aria-current="page"':'' ?>><?= e($label) ?> <b><?= (int)($counts[$label]??0) ?></b></a><?php endforeach; ?></nav>
<?php if(!$orders): ?><section class="customer-panel customer-empty"><i class="bi bi-bag" aria-hidden="true"></i><h2><?= $filter?'Tidak ada pesanan '.e(strtolower($filter)):'Belum ada pesanan' ?></h2><p>Pesanan Anda akan tampil di sini setelah checkout.</p><a class="btn btn-dark" href="?page=catalog">Jelajahi parfum</a></section><?php endif; ?>
<?php foreach($orders as $order): ?><article class="customer-panel customer-order"><header class="customer-panel-heading"><div><h2><?= e($order['order_code']) ?></h2><p><?= e(date('d M Y · H:i',strtotime($order['created_at']))) ?></p></div><span class="customer-status" data-status="<?= e($order['status']) ?>"><?= e($order['status']) ?></span></header>
<div class="customer-order-items"><?php foreach($orderItems[$order['id']]??[] as $item): ?><div class="customer-order-item"><?php if(!empty($item['image'])): ?><a href="?page=product&amp;id=<?= (int)$item['product_id'] ?>"><img src="<?= e($item['image']) ?>" alt="<?= e($item['product_name']) ?>" loading="lazy"></a><?php else: ?><span class="customer-image-placeholder"><i class="bi bi-box" aria-hidden="true"></i></span><?php endif; ?><div><h3><?= e($item['product_name']) ?></h3><small><?= (int)($item['qty']>0?$item['qty']:$item['quantity']) ?> unit</small><?php if($order['status']==='Selesai'&&!empty($item['product_id'])): ?><a href="?page=product&amp;id=<?= (int)$item['product_id'] ?>#reviews">Beri penilaian</a><?php endif; ?></div><strong><?= rupiah($item['subtotal']) ?></strong></div><?php endforeach; ?></div>
<div class="customer-order-footer"><span><?= e($order['shipping_method']) ?> · <?= e($order['payment_method']) ?></span><div>Total pembayaran <strong><?= rupiah(order_payment_total($order)) ?></strong><?php if(!empty($order['payment_unique_code'])): ?><small>Kode unik +<?= rupiah($order['payment_unique_code']) ?></small><?php endif; ?></div></div>
<div class="customer-order-actions"><?php if($order['payment_method']!=='COD'&&in_array($order['status'],['Diproses','Dikemas'],true)&&in_array($order['payment_status'],['manual','pending','Belum diverifikasi'],true)): ?><a class="btn btn-dark" href="?page=awaiting-payment&amp;id=<?= (int)$order['id'] ?>">Lanjutkan pembayaran</a><?php endif; ?><?php if(!($order['tracking_hidden']??false)&&$order['status']!=='Dibatalkan'): ?><a class="btn btn-outline" href="?page=tracking&amp;id=<?= urlencode($order['order_code']) ?>">Lacak pesanan</a><?php endif; ?><a class="btn btn-outline" href="?page=contact">Hubungi toko</a></div>
<details class="customer-order-details"><summary>Detail pengiriman dan biaya</summary><p>Alamat: <?= e($order['address']) ?></p><p>Subtotal <?= rupiah($order['subtotal']) ?> · Ongkir <?= rupiah($order['shipping_cost']) ?></p></details>
<?php if(($order['payment_provider']??'manual')==='midtrans'||in_array($order['status'],['Diproses','Dikemas'],true)): ?><details class="customer-order-details" open><summary>Instruksi pembayaran</summary><?php $instructionSettings=$paymentSnapshots[$order['id']]??payment_settings();$instructionMethod=$order['payment_method'];$instructionOrder=$order;include __DIR__.'/../includes/payment-instructions.php';unset($instructionOrder); ?></details><?php endif; ?>
<?php if(customer_order_can_cancel($order)): ?><details class="customer-cancel"><summary>Batalkan pesanan</summary><p>Pesanan yang belum dikirim dapat dibatalkan. Jika sudah membayar, pengembalian dana perlu dikonfirmasi ke toko.</p><form method="post" onsubmit="return confirm('Batalkan pesanan ini?')"><input type="hidden" name="action" value="customer_order_cancel"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="csrf" value="<?= e(auth_csrf()) ?>"><label>Alasan pembatalan<select name="reason" required><option value="">Pilih alasan</option><option>Ingin mengubah produk atau jumlah</option><option>Alamat pengiriman salah</option><option>Ingin mengganti metode pembayaran</option><option>Berubah pikiran</option></select></label><button type="submit" class="btn customer-cancel-button">Konfirmasi pembatalan</button></form></details><?php elseif($order['status']==='Dibatalkan'): ?><p class="customer-order-note">Pesanan dibatalkan. Untuk pembayaran yang sudah dilakukan, hubungi toko mengenai pengembalian dana.</p><?php elseif(in_array($order['status'],['Dikirim','Selesai'],true)): ?><p class="customer-order-note">Pesanan sudah dikirim sehingga pembatalan langsung tidak tersedia. Hubungi toko untuk bantuan.</p><?php endif; ?>
<?php if(in_array($order['status'],['Dikirim','Selesai'],true)): ?><details class="customer-cancel"><summary>Ajukan retur atau penukaran</summary><form method="post"><input type="hidden" name="action" value="return_request"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><label>Jenis<select name="request_type"><option value="return">Pengembalian</option><option value="exchange">Penukaran</option></select></label><label>Alasan<textarea name="reason" maxlength="3000" required></textarea></label><button class="btn btn-outline">Kirim pengajuan</button></form></details><?php endif; ?>
</article><?php endforeach; ?></div></div></section>

